CREATE TABLE app_users (id UUID PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE bathrooms (id UUID PRIMARY KEY, author_id UUID NOT NULL REFERENCES app_users(id), status VARCHAR(20) NOT NULL, reason VARCHAR(500), created_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, name VARCHAR(120) NOT NULL, address VARCHAR(300) NOT NULL, category VARCHAR(80) NOT NULL, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, access VARCHAR(20) NOT NULL, access_details VARCHAR(300), hours VARCHAR(200), accessible BOOLEAN, items VARCHAR(400) NOT NULL, demo BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE reviews (id UUID PRIMARY KEY, author_id UUID NOT NULL REFERENCES app_users(id), status VARCHAR(20) NOT NULL, reason VARCHAR(500), created_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, bathroom_id UUID NOT NULL REFERENCES bathrooms(id), cleanliness INTEGER NOT NULL CHECK(cleanliness BETWEEN 1 AND 5), structure INTEGER NOT NULL CHECK(structure BETWEEN 1 AND 5), comment VARCHAR(1500));
CREATE TABLE photos (id UUID PRIMARY KEY, author_id UUID NOT NULL REFERENCES app_users(id), status VARCHAR(20) NOT NULL, reason VARCHAR(500), created_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, bathroom_id UUID NOT NULL REFERENCES bathrooms(id), review_id UUID REFERENCES reviews(id), data BYTEA NOT NULL);
CREATE TABLE reports (id UUID PRIMARY KEY, target_type VARCHAR(20) NOT NULL, target_id UUID NOT NULL, reason VARCHAR(40) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, resolved BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE moderation_audit (id UUID PRIMARY KEY, target_type VARCHAR(20) NOT NULL, target_id UUID NOT NULL, moderator_id UUID NOT NULL REFERENCES app_users(id), decision VARCHAR(20) NOT NULL, reason VARCHAR(500) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX bathrooms_status_idx ON bathrooms(status);
CREATE INDEX reviews_bathroom_status_idx ON reviews(bathroom_id, status);
CREATE INDEX photos_bathroom_status_idx ON photos(bathroom_id, status);
